"""Post-hoc descriptive trajectory analysis; no fitting, model calls or noise inference."""
from pathlib import Path
from collections import Counter
from itertools import combinations
import csv,hashlib,json,math
R=Path(__file__).resolve().parents[1];SRC=R/'analysis/generation-comparison-v2/generation-comparison.json';OUT=R/'analysis/generation-patterns-v1';TOL=1e-9
LOWER={'A14','B03','B07','B08','D02','E06','F04','H16','K05','L06','M01','M04'}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def mean(x):return sum(x)/len(x) if x else None
def sign(x):return 1 if x>TOL else -1 if x< -TOL else 0
def classify(ds):
 if any(x is None for x in ds):return 'incomplete'
 ss=[sign(x) for x in ds]
 if all(s==1 for s in ss):return 'strictly_improving'
 if all(s==-1 for s in ss):return 'strictly_declining'
 if all(s==0 for s in ss):return 'numerically_flat'
 if all(s>=0 for s in ss):return 'nondecreasing_with_ties'
 if all(s<=0 for s in ss):return 'nonincreasing_with_ties'
 return 'mixed_reversals'
def summarize(tasks,a,b,strict=False):
 counts=Counter();ids={k:[] for k in ['better','worse','numerical_tie','incomplete','format_ineligible']}
 for t in tasks:
  x,y=t['scores'][a],t['scores'][b]
  k='incomplete' if x is None or y is None else 'format_ineligible' if strict and not (t['format_compliant'][a] and t['format_compliant'][b]) else {1:'better',-1:'worse',0:'numerical_tie'}[sign((y-x)*t['orientation'])]
  counts[k]+=1;ids[k].append(t['benchmark_id'])
 complete=counts['better']+counts['worse']+counts['numerical_tie']
 return dict(older=a,newer=b,n_tasks=len(tasks),counts={k:counts[k] for k in ids},task_ids=ids,complete_pairs=complete,better_fraction_of_complete=counts['better']/complete if complete else None)
def csvwrite(name,rows):
 with (OUT/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
def main():
 source=json.loads(SRC.read_text());models=source['models'];tasks=[];audit=[]
 for t in source['tasks']:
  tid=t['benchmark_id'];expected='lower' if tid in LOWER else 'higher';assert t['direction']==expected,tid
  for row in t['chart_rows']:assert row['direction']==expected,(tid,row['model'])
  orient=1 if expected=='higher' else -1;values=[t['scores'][m] for m in models]
  gains=[(b-a)*orient if a is not None and b is not None else None for a,b in zip(values,values[1:])];shape=classify(gains)
  signs=[sign(x) for x in gains if x is not None];nonzero=[s for s in signs if s];reversals=sum(a!=b for a,b in zip(nonzero,nonzero[1:])) if len(signs)==3 else None
  complete=all(v is not None for v in values);fmt=all(t['format_compliant'][m] for m in models)
  decreasing=all(a>b+TOL for a,b in zip(gains,gains[1:])) if shape=='strictly_improving' else None
  row=dict(benchmark_id=tid,task=t['task'],family=t['family_code'],family_name=t['family_name'],metric=t['metric'],direction=expected,orientation=orient,scores=t['scores'],format_compliant=t['format_compliant'],observed_macro_eligible=t['observed_macro_eligible'],complete_trajectory=complete,strict_complete=complete and fmt,adjacent_direction_adjusted_gains=gains,step_pattern=' '.join('?' if x is None else {1:'+',-1:'-',0:'='}[sign(x)] for x in gains),trajectory_class=shape,n_sign_reversals=reversals,diminishing_every_step=decreasing,last_gain_smaller_than_first=gains[-1]<gains[0]-TOL if shape=='strictly_improving' else None,randomness_assessment='not_estimated',equivalence_assessment='not_established',caveat=t['interpretation'])
  tasks.append(row);audit.append(dict(benchmark_id=tid,metric=t['metric'],direction=expected,line_visual='better scores higher on page; native axis retained',bar_visual='raw native scores; lower values better' if expected=='lower' else 'raw native scores; higher values better',special_caveat='C2ST target is 0.5; near-chance ordering is not sampler superiority' if tid=='L06' else ''))
 assert len(tasks)==30 and len({t['family'] for t in tasks})==14
 pairs=[summarize(tasks,a,b) for a,b in combinations(models,2)];endpoint=pairs[2];assert endpoint['older']==models[0] and endpoint['newer']==models[-1]
 classes={k:sum(t['trajectory_class']==k for t in tasks) for k in ['strictly_improving','mixed_reversals','numerically_flat','strictly_declining','nondecreasing_with_ties','nonincreasing_with_ties','incomplete']}
 monotonic=[t for t in tasks if t['trajectory_class']=='strictly_improving'];complete=[t for t in tasks if t['complete_trajectory']];strict=[t for t in tasks if t['strict_complete']]
 families=[]
 for family in sorted({t['family'] for t in tasks}):
  ts=[t for t in tasks if t['family']==family];ep=summarize(ts,models[0],models[-1]);families.append(dict(family=family,name=ts[0]['family_name'],n_tasks=len(ts),complete_trajectories=sum(t['complete_trajectory'] for t in ts),strictly_improving=sum(t['trajectory_class']=='strictly_improving' for t in ts),mixed_reversals=sum(t['trajectory_class']=='mixed_reversals' for t in ts),incomplete=sum(not t['complete_trajectory'] for t in ts),endpoint_counts=ep['counts']))
 d=dict(revision='generation-patterns-v1',analysis_type='post-hoc descriptive; no new API calls or executions',models=models,n_tasks=30,n_families=14,n_complete_trajectories=len(complete),endpoint=endpoint,pair_summaries=pairs,strict_endpoint=summarize(tasks,models[0],models[-1],True),observed_endpoint=summarize([t for t in tasks if t['observed_macro_eligible']],models[0],models[-1]),first_attempt_endpoint=next(r for r in source['first_attempt_task_direction_summaries'] if r['scope']=='all_measured_tasks' and r['older']==models[0] and r['newer']==models[-1]),trajectory_counts=classes,strict_trajectory_counts=dict(Counter(t['trajectory_class'] for t in strict)),strict_complete_trajectories=len(strict),step_pattern_counts=dict(Counter(t['step_pattern'] for t in complete)),monotonic_task_ids=[t['benchmark_id'] for t in monotonic],monotonic_family_count=len({t['family'] for t in monotonic}),diminishing_gains=dict(n_monotonic=len(monotonic),strictly_diminishing=sum(t['diminishing_every_step'] for t in monotonic),last_smaller_than_first=sum(t['last_gain_smaller_than_first'] for t in monotonic),strictly_diminishing_task_ids=[t['benchmark_id'] for t in monotonic if t['diminishing_every_step']],warning='Within-task ordinal score gaps only; version steps are not equal compute or elapsed time. Selection is conditional on monotonic trajectories.'),randomness=dict(classification='not_identifiable_from_this_panel',n_tasks_with_validated_four_model_generation_noise_model=0,equivalence_margin_predeclared=False,numerical_tie_tolerance=TOL,explanation='Mixed signs are reversals, not evidence of chance performance or random model differences. Non-significance and practical equivalence cannot be inferred from a small point difference.'),metric_direction_counts=dict(Counter(t['direction'] for t in tasks)),family_summaries=families,tasks=tasks,input_sha256={str(SRC.relative_to(R)):sha(SRC),str(Path(__file__).relative_to(R)):sha(Path(__file__))})
 repairs=json.loads((R/'results/generation-repairs-v1.json').read_text());d['repair_summary']={k:repairs[k] for k in ['original_runtime_failures','recovered_original_runtime_failures','remaining_unscored','successful_repair_slice_outputs','new_API_calls']};d['input_sha256']['results/generation-repairs-v1.json']=sha(R/'results/generation-repairs-v1.json');OUT.mkdir(parents=True,exist_ok=True);write(OUT/'patterns.json',d);write(R/'website/data/generation-patterns.json',d)
 csvwrite('task-patterns.csv',[{k:t[k] for k in ['benchmark_id','family','task','metric','direction','step_pattern','trajectory_class','n_sign_reversals','complete_trajectory','strict_complete','diminishing_every_step','last_gain_smaller_than_first','randomness_assessment','equivalence_assessment']} for t in tasks])
 csvwrite('metric-direction-audit.csv',audit);csvwrite('category-patterns.csv',[{k:v for k,v in f.items() if k!='endpoint_counts'}|{('endpoint_'+k):v for k,v in f['endpoint_counts'].items()} for f in families])
 write(OUT/'methods.json',dict(numerical_tolerance=TOL,orientation='higher: +1; lower: -1; multiply every adjacent and endpoint delta by orientation',task_weighting='Each task once; source report equal-slice native mean, only if every slice succeeds',missing_policy='Incomplete, never zero; partial trajectories not assigned full four-point shapes',strict_sensitivity='All four models numeric and line-compliant on every slice',inference='No p-values, confidence intervals, statistical-equivalence or randomness labels. Generation replicates and independent biological units differ by task. Source cohorts overlap across categories.',retrospective='Trajectory and diminishing-gain analyses selected after seeing results; exploratory. Nine monotonic tasks are not nine independent confirmations of a scaling law.',provenance='Final usability uses explicit historical repair overlay. API/Codex wrappers, reasoning controls and repair histories differ. First-attempt and observed-data sensitivities retained.'))
 render_report(d)
 print(json.dumps({k:d[k] for k in ['endpoint','trajectory_counts','strict_trajectory_counts','step_pattern_counts','diminishing_gains','metric_direction_counts']},indent=2))
def render_report(d):
 e=d['endpoint'];c=e['counts'];g=d['diminishing_gains'];sc=d['strict_endpoint']['counts'];oc=d['observed_endpoint']['counts'];fc=d['first_attempt_endpoint']['counts'];rep=d['repair_summary']
 lines=['# Macro patterns after repair and exclusion review','',f"GPT-6.1 versus GPT-4.1: **{c['better']} better, {c['worse']} worse, {c['numerical_tie']} numerical ties, {c['incomplete']} incomplete** out of {d['n_tasks']} tasks. {c['better']}/{e['complete_pairs']} comparable task means ({100*e['better_fraction_of_complete']:.1f}%) favor GPT-6.1. This is a task-count fraction, not model accuracy or a probability for all neuroscience problems.",'',f"Before these macros, {rep['recovered_original_runtime_failures']}/{rep['original_runtime_failures']} original API-runtime failures were recovered and independently audited. {rep['remaining_unscored']} model/task cases remain unscored within the original 180-second limit. Original failed runs remain intact. Physical-line repairs preserve the exact AST; they demonstrate manually formatted compliance, not original model brevity. No new API calls were made.",'','## Quantitative findings','','| Four-model trajectory | Tasks |','|---|---:|']
 lines += [f'| {k.replace("_"," ")} | {v} |' for k,v in d['trajectory_counts'].items()]
 mono=d['trajectory_counts']['strictly_improving'];lines += ['',f"{mono}/{d['n_complete_trajectories']} complete trajectories ({100*mono/d['n_complete_trajectories']:.1f}%; {mono}/{d['n_tasks']} of the attempted panel) improve at every adjacent step, spanning {d['monotonic_family_count']} categories: "+', '.join(d['monotonic_task_ids'])+'.','',f"Strict-format sensitivity has {d['strict_complete_trajectories']} complete trajectories: "+str(d['strict_trajectory_counts'])+'. All manual formatting is still excluded from original model-compliance claims.', '',f"Endpoint sensitivities (better / worse / numerical tie / incomplete): strict-format {sc['better']} / {sc['worse']} / {sc['numerical_tie']} / {sc['incomplete']}, with {sc['format_ineligible']} additionally format-ineligible; observed-data {oc['better']} / {oc['worse']} / {oc['numerical_tie']} / {oc['incomplete']}; untouched first attempts {fc['better']} / {fc['worse']} / {fc['numerical_tie']} / {fc['incomplete']}. These scopes and repair histories answer different questions.", '', '| Adjacent sign pattern (+ = improvement) | Complete tasks |','|---|---:|']
 lines += [f'| {k} | {v} |' for k,v in sorted(d['step_pattern_counts'].items())]
 lines += ['',f"Among {g['n_monotonic']} strictly improving trajectories, {g['strictly_diminishing']} have successively smaller gains ({', '.join(g['strictly_diminishing_task_ids'])}); {g['last_smaller_than_first']} have a smaller final than first gain. These are within-task native score gaps. Versions are not equally spaced compute/time measurements. This conditional post-hoc pattern cannot establish diminishing returns or a scaling exponent.", '', 'Endpoint regressions relative to GPT-4.1: '+', '.join(e['task_ids']['worse'])+'. All task IDs, directions, category denominators and six model pairs are retained in the data files.', '', '## Qualitative findings','','Mixed changes are reversals, not established randomness. No validated four-model generation-noise model or prospective equivalence margins exist. Zero numerical endpoint ties does not imply no practically equivalent or statistically unresolved outcomes. A small gap is not evidence of equality; a nonmonotonic curve is not proof of random performance. Chance classifier accuracy is a separate concept.','','Untouched failures involved library compatibility, grouped-CV misuse, syntax, array indexing/shapes, legacy HDF5 aliases and time limits. Repairs enable usable procedures; optimizer replacements and the J08 GPT-4.1 bootstrap-budget adaptation can change predictions. J08 caps each tree at 250000 bootstrap draws rather than 16451616, preserving the original 180-second limit. That point is manually budget-adapted and is not untouched GPT-4.1 performance. Excluding the manually budget-adapted J08 point leaves the previous endpoint result: GPT-6.1 improves on 27 of 29 comparable tasks, with two regressions. Thus the final panel combines model-written programs with explicit manual engineering. It cannot isolate autonomous debugging or causal generation effects.','','The monotonic trajectories span calcium inference, population inference, sensory encoding, EEG decoding, cell classification and statistical inference. Behavior/movement and extracellular tasks have reversals in every complete trajectory in those categories. This retrospective observation has small and overlapping source samples; representation, estimator choice and task structure are hypotheses, not identified causal explanations.','','## Quantitative + qualitative findings','','- **P300 (H02):** 0.5731 → 0.7458 → 0.7572 → 0.7885 AUC; the ordering is consistent, but the last gain exceeds the middle one. Ten held-out people are not independent model-generation replicates.','- **Encoding/inference:** C05, F04, K06, L04 and L06 have shrinking adjacent score gains. L06 approaches the C2ST target 0.5; finite classifier noise limits interpreting near-chance ordering.','- **Method/representation hypothesis:** E01 changes from poor negative bits/spike to positive values. Investigate rate calibration and estimator choices before interpreting this as general neural understanding.','- **Ceiling ties:** N05 now follows 0 → 1 → 1 → 1 after explicit parser repairs; later models tie on 61 fields from one file. That plateau is a bounded task ceiling, not evidence of general model stagnation.', '- **Tiny gaps:** A15 endpoint gain is about 0.000119 F1 and I10 about 0.005263 balanced accuracy. The signs are positive, but practical relevance and statistical equivalence are unestablished.','- **Exceptions:** GPT-4.1 wins B07 compression and K05 marker-fraction calibration against GPT-6.1. GPT-5 peaks on I07/I10. These counterexamples support task-level validation rather than an always-newest rule.','- **Repairs are not capabilities:** Recovering an execution failure improves usability coverage. It is not evidence that the untouched model could produce or debug the repaired program without help.','','## Metric direction and graph conventions','',f"All {d['n_tasks']} tasks and reference rows pass an explicit direction audit: {d['metric_direction_counts']['higher']} higher-is-better, {d['metric_direction_counts']['lower']} lower-is-better primary metrics. Every line plot puts better native scores higher on the page; lower-is-better vertical axes are reversed and labeled. Bars retain native values with an explicit direction key. Negative values make bar length alone misleading. C2ST retains the frozen lower-is-better convention with an explicit target-0.5 caveat.", '', '## Reproduce and audit','','Run `python3 scripts/analyze_generation_patterns.py` and `python3 scripts/check_generation_patterns.py`. No new generation or score fitting occurs. Original measurements and previous macro snapshots remain intact.','','- [Lag-1/2/3 comparisons and change-size sensitivity bands](../generation-lags-v1/report.md)','- [Methods and limits](methods.json)','- [All per-task classifications](task-patterns.csv)','- [Category counts](category-patterns.csv)','- [Metric-direction audit](metric-direction-audit.csv)','- [Derived data and input hashes](patterns.json)','- [Current native scores](../generation-comparison-v2/task-scores.csv)','- [Current four-model report and first-attempt sensitivity](../generation-comparison-v2/report.md)','- [Every repair, failed revision and exclusion](../../experiments/generation-repairs-v1/README.md)','- [Original four-model snapshot](../generation-comparison-v1/report.md)','- [Thirty specialist source reviews](../../literature/specialist-review-2026-11-01/)']
 (OUT/'report.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
